// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

contract ContractDevVault {
    address public owner;
    uint256 public totalDeposits;
    uint256 public totalWithdrawals;
    uint256 public totalAssets;
    uint256 public vaultBalance;

    struct Asset {
        address tokenAddress;
        string symbol;
        uint256 balance;
        uint256 price;
        bool isActive;
    }

    struct Deposit {
        uint256 id;
        address user;
        address tokenAddress;
        uint256 amount;
        uint256 timestamp;
        string status;
    }

    struct Withdrawal {
        uint256 id;
        address user;
        address tokenAddress;
        uint256 amount;
        uint256 timestamp;
        string status;
    }

    mapping(uint256 => Asset) public assets;
    mapping(uint256 => Deposit) public deposits;
    mapping(uint256 => Withdrawal) public withdrawals;
    mapping(address => uint256) public userBalances;
    mapping(address => bool) public supportedTokens;

    uint256 public assetCount;
    uint256 public depositCount;
    uint256 public withdrawalCount;

    event AssetAdded(uint256 indexed assetId, address tokenAddress, string symbol, uint256 price);
    event AssetUpdated(uint256 indexed assetId, uint256 newPrice);
    event DepositMade(uint256 indexed depositId, address indexed user, address tokenAddress, uint256 amount);
    event WithdrawalMade(uint256 indexed withdrawalId, address indexed user, address tokenAddress, uint256 amount);
    event VaultBalanceUpdated(uint256 newBalance);
    event OwnerChanged(address indexed oldOwner, address indexed newOwner);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    function addAsset(
        address _tokenAddress,
        string memory _symbol,
        uint256 _price
    ) public onlyOwner returns (uint256) {
        require(_tokenAddress != address(0), "Invalid token address");
        require(_price > 0, "Price must be greater than 0");

        uint256 assetId = assetCount;
        assets[assetId] = Asset({
            tokenAddress: _tokenAddress,
            symbol: _symbol,
            balance: 0,
            price: _price,
            isActive: true
        });

        supportedTokens[_tokenAddress] = true;
        assetCount++;
        totalAssets++;

        emit AssetAdded(assetId, _tokenAddress, _symbol, _price);
        return assetId;
    }

    function updateAssetPrice(uint256 _assetId, uint256 _newPrice) public onlyOwner {
        require(_assetId < assetCount, "Asset does not exist");
        require(_newPrice > 0, "Price must be greater than 0");

        assets[_assetId].price = _newPrice;

        emit AssetUpdated(_assetId, _newPrice);
    }

    function depositAsset(
        address _tokenAddress,
        uint256 _amount
    ) public returns (uint256) {
        require(supportedTokens[_tokenAddress], "Token not supported");
        require(_amount > 0, "Amount must be greater than 0");

        // Find the asset
        uint256 assetId = _findAssetByToken(_tokenAddress);
        require(assetId < assetCount, "Asset not found");

        // Update balances
        assets[assetId].balance += _amount;
        userBalances[msg.sender] += _amount;
        vaultBalance += _amount;
        totalDeposits += _amount;

        // Create deposit record
        uint256 depositId = depositCount;
        deposits[depositId] = Deposit({
            id: depositId,
            user: msg.sender,
            tokenAddress: _tokenAddress,
            amount: _amount,
            timestamp: block.timestamp,
            status: "Completed"
        });

        depositCount++;

        emit DepositMade(depositId, msg.sender, _tokenAddress, _amount);
        emit VaultBalanceUpdated(vaultBalance);

        return depositId;
    }

    function withdrawAsset(
        address _tokenAddress,
        uint256 _amount
    ) public returns (uint256) {
        require(supportedTokens[_tokenAddress], "Token not supported");
        require(_amount > 0, "Amount must be greater than 0");
        require(userBalances[msg.sender] >= _amount, "Insufficient balance");

        // Find the asset
        uint256 assetId = _findAssetByToken(_tokenAddress);
        require(assetId < assetCount, "Asset not found");
        require(assets[assetId].balance >= _amount, "Insufficient vault balance");

        // Update balances
        assets[assetId].balance -= _amount;
        userBalances[msg.sender] -= _amount;
        vaultBalance -= _amount;
        totalWithdrawals += _amount;

        // Create withdrawal record
        uint256 withdrawalId = withdrawalCount;
        withdrawals[withdrawalId] = Withdrawal({
            id: withdrawalId,
            user: msg.sender,
            tokenAddress: _tokenAddress,
            amount: _amount,
            timestamp: block.timestamp,
            status: "Completed"
        });

        withdrawalCount++;

        emit WithdrawalMade(withdrawalId, msg.sender, _tokenAddress, _amount);
        emit VaultBalanceUpdated(vaultBalance);

        return withdrawalId;
    }

    function _findAssetByToken(address _tokenAddress) internal view returns (uint256) {
        for (uint256 i = 0; i < assetCount; i++) {
            if (assets[i].tokenAddress == _tokenAddress && assets[i].isActive) {
                return i;
            }
        }
        return assetCount; // Return invalid ID if not found
    }

    function getAsset(uint256 _assetId) public view returns (
        address tokenAddress,
        string memory symbol,
        uint256 balance,
        uint256 price,
        bool isActive
    ) {
        require(_assetId < assetCount, "Asset does not exist");

        Asset memory asset = assets[_assetId];
        return (
            asset.tokenAddress,
            asset.symbol,
            asset.balance,
            asset.price,
            asset.isActive
        );
    }

    function getDeposit(uint256 _depositId) public view returns (
        uint256 id,
        address user,
        address tokenAddress,
        uint256 amount,
        uint256 timestamp,
        string memory status
    ) {
        require(_depositId < depositCount, "Deposit does not exist");

        Deposit memory deposit = deposits[_depositId];
        return (
            deposit.id,
            deposit.user,
            deposit.tokenAddress,
            deposit.amount,
            deposit.timestamp,
            deposit.status
        );
    }

    function getWithdrawal(uint256 _withdrawalId) public view returns (
        uint256 id,
        address user,
        address tokenAddress,
        uint256 amount,
        uint256 timestamp,
        string memory status
    ) {
        require(_withdrawalId < withdrawalCount, "Withdrawal does not exist");

        Withdrawal memory withdrawal = withdrawals[_withdrawalId];
        return (
            withdrawal.id,
            withdrawal.user,
            withdrawal.tokenAddress,
            withdrawal.amount,
            withdrawal.timestamp,
            withdrawal.status
        );
    }

    function getVaultStats() public view returns (
        uint256 _totalDeposits,
        uint256 _totalWithdrawals,
        uint256 _totalAssets,
        uint256 _vaultBalance,
        uint256 _assetCount
    ) {
        return (totalDeposits, totalWithdrawals, totalAssets, vaultBalance, assetCount);
    }

    function getUserBalance(address _user) public view returns (uint256) {
        return userBalances[_user];
    }

    function updateOwner(address _newOwner) public onlyOwner {
        require(_newOwner != address(0), "New owner cannot be the zero address");
        address oldOwner = owner;
        owner = _newOwner;
        emit OwnerChanged(oldOwner, _newOwner);
    }
}

project/contracts/ContractDevWETHDeposit.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

interface IWETH {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ContractDevWETHDepositor {
    address public owner;
    address public wethAddress;
    IWETH public weth;

    uint256 public totalETHDeposited;
    uint256 public totalWETHDeposited;
    uint256 public totalWETHWithdrawn;

    mapping(address => uint256) public userWETHBalance;
    mapping(address => uint256) public userETHDeposited;

    struct Deposit {
        address user;
        uint256 ethAmount;
        uint256 wethAmount;
        uint256 timestamp;
    }

    mapping(uint256 => Deposit) public deposits;
    uint256 public depositCount;

    event ETHReceived(address indexed sender, uint256 amount);
    event ETHDepositedToWETH(
        address indexed user,
        uint256 ethAmount,
        uint256 wethAmount
    );
    event WETHWithdrawn(
        address indexed user,
        uint256 wethAmount,
        uint256 ethAmount
    );
    event WETHTransferred(
        address indexed from,
        address indexed to,
        uint256 amount
    );
    event OwnerChanged(address indexed oldOwner, address indexed newOwner);
    event WETHAddressUpdated(address indexed oldAddress, address indexed newAddress);

    constructor(address _wethAddress) {
        owner = msg.sender;
        require(_wethAddress != address(0), "WETH address cannot be zero");
        wethAddress = _wethAddress;
        weth = IWETH(_wethAddress);
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    // Receive ETH and automatically deposit to WETH
    receive() external payable {
        require(msg.value > 0, "Must send ETH");
        _depositToWETH(msg.sender, msg.value);
    }

    // Fallback function for ETH
    fallback() external payable {
        if (msg.value > 0) {
            _depositToWETH(msg.sender, msg.value);
        }
    }

    // Manual deposit function
    function depositETH() public payable {
        require(msg.value > 0, "Must send ETH");
        _depositToWETH(msg.sender, msg.value);
    }

    // Internal function to handle WETH deposit
    function _depositToWETH(address _user, uint256 _ethAmount) internal {
        // Get WETH balance before deposit
        uint256 wethBalanceBefore = weth.balanceOf(address(this));

        // Deposit ETH to WETH contract
        weth.deposit{value: _ethAmount}();

        // Get the WETH amount received (should be 1:1 with ETH)
        uint256 wethBalanceAfter = weth.balanceOf(address(this));
        uint256 wethAmount = wethBalanceAfter - wethBalanceBefore;

        // Update balances
        userWETHBalance[_user] += wethAmount;
        userETHDeposited[_user] += _ethAmount;
        totalETHDeposited += _ethAmount;
        totalWETHDeposited += wethAmount;

        // Record deposit
        deposits[depositCount] = Deposit({
            user: _user,
            ethAmount: _ethAmount,
            wethAmount: wethAmount,
            timestamp: block.timestamp
        });
        depositCount++;

        emit ETHReceived(_user, _ethAmount);
        emit ETHDepositedToWETH(_user, _ethAmount, wethAmount);
    }

    // Withdraw WETH back to ETH
    function withdrawWETH(uint256 _amount) public {
        require(_amount > 0, "Amount must be greater than 0");
        require(
            userWETHBalance[msg.sender] >= _amount,
            "Insufficient WETH balance"
        );
        require(
            weth.balanceOf(address(this)) >= _amount,
            "Contract has insufficient WETH"
        );

        // Update balances
        userWETHBalance[msg.sender] -= _amount;
        totalWETHWithdrawn += _amount;

        // Withdraw WETH to ETH
        weth.withdraw(_amount);

        // Transfer ETH to user
        (bool success, ) = payable(msg.sender).call{value: _amount}("");
        require(success, "ETH transfer failed");

        emit WETHWithdrawn(msg.sender, _amount, _amount);
    }

    // Withdraw all WETH for user
    function withdrawAllWETH() public {
        uint256 balance = userWETHBalance[msg.sender];
        require(balance > 0, "No WETH balance to withdraw");
        withdrawWETH(balance);
    }

    // Transfer WETH to another address (transfers within this contract's tracking system)
    function transferWETH(address _to, uint256 _amount) public {
        require(_to != address(0), "Cannot transfer to zero address");
        require(_amount > 0, "Amount must be greater than 0");
        require(
            userWETHBalance[msg.sender] >= _amount,
            "Insufficient WETH balance"
        );
        require(
            weth.balanceOf(address(this)) >= _amount,
            "Contract has insufficient WETH"
        );

        // Update balances (WETH stays in contract, just tracking changes)
        userWETHBalance[msg.sender] -= _amount;
        userWETHBalance[_to] += _amount;

        emit WETHTransferred(msg.sender, _to, _amount);
    }

    // Transfer WETH tokens out of the contract to an external address
    function transferWETHToExternal(address _to, uint256 _amount) public {
        require(_to != address(0), "Cannot transfer to zero address");
        require(_amount > 0, "Amount must be greater than 0");
        require(
            userWETHBalance[msg.sender] >= _amount,
            "Insufficient WETH balance"
        );
        require(
            weth.balanceOf(address(this)) >= _amount,
            "Contract has insufficient WETH"
        );

        // Update balance
        userWETHBalance[msg.sender] -= _amount;

        // Transfer WETH tokens to external address
        require(
            weth.transfer(_to, _amount),
            "WETH transfer failed"
        );

        emit WETHTransferred(msg.sender, _to, _amount);
    }

    // Get user's WETH balance
    function getUserWETHBalance(address _user) public view returns (uint256) {
        return userWETHBalance[_user];
    }

    // Get contract's total WETH balance
    function getContractWETHBalance() public view returns (uint256) {
        return weth.balanceOf(address(this));
    }

    // Get contract's ETH balance
    function getContractETHBalance() public view returns (uint256) {
        return address(this).balance;
    }

    // Get deposit info
    function getDeposit(uint256 _depositId) public view returns (
        address user,
        uint256 ethAmount,
        uint256 wethAmount,
        uint256 timestamp
    ) {
        require(_depositId < depositCount, "Deposit does not exist");
        Deposit memory deposit = deposits[_depositId];
        return (
            deposit.user,
            deposit.ethAmount,
            deposit.wethAmount,
            deposit.timestamp
        );
    }

    // Owner functions
    function updateWETHAddress(address _newWETHAddress) public onlyOwner {
        require(_newWETHAddress != address(0), "WETH address cannot be zero");
        address oldAddress = wethAddress;
        wethAddress = _newWETHAddress;
        weth = IWETH(_newWETHAddress);
        emit WETHAddressUpdated(oldAddress, _newWETHAddress);
    }

    function updateOwner(address _newOwner) public onlyOwner {
        require(
            _newOwner != address(0),
            "New owner cannot be the zero address"
        );
        address oldOwner = owner;
        owner = _newOwner;
        emit OwnerChanged(oldOwner, _newOwner);
    }

    // Emergency function to withdraw any stuck ETH (only owner)
    function emergencyWithdrawETH(uint256 _amount) public onlyOwner {
        require(_amount <= address(this).balance, "Insufficient ETH balance");
        (bool success, ) = payable(owner).call{value: _amount}("");
        require(success, "ETH transfer failed");
    }
}

